def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}  # name -> [balance, frozen]
    history = []   # snapshots of affected accounts before each successful op
    rejected = []

    def valid_amount(tok):
        return len(tok) > 0 and all(c in "0123456789" for c in tok)

    def save(names):
        return {n: (list(accounts[n]) if n in accounts else None) for n in names}

    for i, op in enumerate(ops):
        parts = op.split(" ")
        verb, args = parts[0], parts[1:]
        ok = True
        snap = None

        if verb == "undo":
            if args or not history:
                ok = False
            else:
                for name, old in history.pop().items():
                    if old is None:
                        accounts.pop(name, None)
                    else:
                        accounts[name] = old
            if not ok:
                rejected.append(i)
            continue

        if verb == "open" and len(args) == 2:
            a, n = args
            if valid_amount(n) and a not in accounts:
                snap = save([a])
                accounts[a] = [int(n), False]
            else:
                ok = False

        elif verb == "deposit" and len(args) == 2:
            a, n = args
            if valid_amount(n) and int(n) > 0 and a in accounts:
                snap = save([a])
                accounts[a][0] += int(n)
            else:
                ok = False

        elif verb == "withdraw" and len(args) == 2:
            a, n = args
            if (valid_amount(n) and int(n) > 0 and a in accounts
                    and not accounts[a][1] and accounts[a][0] >= int(n)):
                snap = save([a])
                accounts[a][0] -= int(n)
            else:
                ok = False

        elif verb == "transfer" and len(args) == 3:
            a, b, n = args
            if (valid_amount(n) and int(n) > 0 and a != b
                    and a in accounts and b in accounts
                    and not accounts[a][1] and accounts[a][0] >= int(n)):
                snap = save([a, b])
                accounts[a][0] -= int(n)
                accounts[b][0] += int(n)
            else:
                ok = False

        elif verb == "freeze" and len(args) == 1:
            a = args[0]
            if a in accounts and not accounts[a][1]:
                snap = save([a])
                accounts[a][1] = True
            else:
                ok = False

        elif verb == "unfreeze" and len(args) == 1:
            a = args[0]
            if a in accounts and accounts[a][1]:
                snap = save([a])
                accounts[a][1] = False
            else:
                ok = False

        else:
            ok = False

        if ok:
            history.append(snap)
        else:
            rejected.append(i)

    balances = {name: state[0] for name, state in accounts.items()}
    return balances, rejected
